                new ReviseIntervalRequest("c1", 100L, 109L, 999, "op", "req-r-409")))
                .isInstanceOf(ConflictException.class);
        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(6);

        // 合法修订成功并推进版本
